      body: '{"type":"EXTERNAL"}',
    });
  });

  it("returns an empty id when the 201 body has none", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn(async () => answer(201, {})),
    );

    await expect(submitRegistration({})).resolves.toEqual({ kind: "created", id: "" });
  });

  it("returns the field errors of a 400", async () => {
